import warp as wpfrom . import collision_driverfrom . import smooth_accfrom . import smooth_actuatorfrom . import smooth_dragfrom . import smooth_muscle_actfrom . import smooth_muscle_ptfrom . import smooth_muscle_eqfrom . import smooth_muscle_fnfrom . import smooth_muscle_metabolicfrom . import smooth_frcfrom . import smooth_hunt_crossleyfrom . import smooth_exponential_limitfrom . import smooth_hc_limitsfrom . import smooth_postfrom . import smooth_posfrom . import smooth_velfrom .types import ContactTypefrom .types import LimitTypefrom .types import Datafrom .types import Modelfrom .warp_util import event_scopewp.set_module_options({"enable_backward": False})@event_scopedef fwd_position(m: Model, d: Data, run_reset: bool = False):    """ Position-dependent computations. """    # If we requested a reset, let's make sure we're within the joint limits    if run_reset:        smooth_pos.fix_qpos_limits(m, d)    smooth_pos.kinematics(m, d)    smooth_pos.com_pos(m, d)    smooth_pos.spatial_inertia(m, d)    collision_driver.collision(m, d)@event_scopedef fwd_velocity(m: Model, d: Data):    """Velocity-dependent computations."""    smooth_vel.link_vel(m, d)    smooth_vel.site_velocity(m, d)@event_scopedef fwd_muscles(m: Model, d: Data, run_reset: bool):    """ Muscle-related computations. """    if not m.nmuscle:        return    # Activation dynamics    smooth_muscle_act.compute_act_dot(m, d)    # Function-path approximation vs point-based path    if wp.static(m.opt.use_fn_path):        smooth_muscle_fn.muscle_path(m, d)    else:        smooth_muscle_pt.muscle_path(m, d)    # Equilibrate on reset    if run_reset:        smooth_muscle_eq.muscle_reset(m, d)    smooth_muscle_eq.realize_muscle_state(m, d)@event_scopedef fwd_actuators(m: Model, d: Data):    """ Actuator-related computations. """    if not m.nactuator:        return    smooth_actuator.compute_act_dot(m, d)@event_scopedef fwd_forces(m: Model, d: Data):    """ Force-related computations. """    smooth_frc.reset_forces(m, d)    # Inverse dynamics for bias forces    smooth_frc.bias_force(m, d)    # Spring, damping, drag    smooth_frc.spring(m, d)    smooth_frc.damping(m, d)    if m.opt.enable_drag:        smooth_drag.drag(m, d)    # Muscles    if wp.static(m.opt.use_fn_path):        smooth_muscle_fn.muscle_force(m, d)    else:        smooth_muscle_pt.muscle_force(m, d)    # Actuators    smooth_actuator.actuator_force(m, d)    # Contact forces    if wp.static(m.opt.contact_type == ContactType.HUNT_CROSSLEY):        smooth_hunt_crossley.contact_forces(m, d)    # Joint limit forces    if wp.static(m.opt.limit_type == LimitType.EXPONENTIAL):        smooth_exponential_limit.limit_forces(m, d)    elif wp.static(m.opt.limit_type == LimitType.HUNT_CROSSLEY):        smooth_hc_limits.limit_forces(m, d)    smooth_frc.accumulate_forces(m, d)@event_scopedef fwd_acceleration(m: Model, d: Data):    """ Computes accelerations """    smooth_acc.crb(m, d)    smooth_acc.factor_m(m, d)    smooth_acc.factor_solve_i(m, d, d.qM, d.qLD, d.qacc, d.qfrc_tau)@event_scopedef post(m: Model, d: Data):    """ Post-processing computations. """    smooth_post.compute_joint_moments(m, d)    smooth_muscle_metabolic.compute_muscle_metabolics(m, d)@event_scopedef fwd(m: Model, d: Data):    """Forward dynamics (i.e., realize state). No integration """    fwd_position(m, d, run_reset=False)    fwd_velocity(m, d)    fwd_muscles(m, d, run_reset=False)    fwd_actuators(m, d)    fwd_forces(m, d)    fwd_acceleration(m, d)@event_scopedef reset(m: Model, d: Data):    """ Called after resetting any of the worlds, realize state """    fwd_position(m, d, run_reset=True)    fwd_velocity(m, d)    fwd_muscles(m, d, run_reset=True)  # equilibrate the muscles    fwd_actuators(m, d)    fwd_forces(m, d)    fwd_acceleration(m, d)    # post(m, d)    # d.world_reset.zero_()@event_scopedef fk(m: Model, d: Data):    """ Forward kinematics only for position-dependent quantities """    fwd_position(m, d)